     1|/**
     2| * IVX AI Provider Layer — Owner-owned, independent from Rork.
     3| *
     4| * This module provides a unified interface for AI providers (OpenAI, Anthropic,
     5| * etc.) that IVX owns and controls directly. It replaces the Vercel AI Gateway
     6| * (Rork-managed) with owner-provided API keys.
     7| *
     8| * Key features:
     9| * - Provider health checks
    10| * - Model selection per task type
    11| * - Chat completion + structured JSON output
    12| * - Timeout + AbortController cancellation
    13| * - Retry with exponential backoff
    14| * - Provider failover
    15| * - Cost tracking with daily/monthly limits
    16| * - Emergency stop
    17| * - No secrets in logs
    18| */
    19|
    20|export type ProviderName = 'openai' | 'anthropic' | 'vercel_gateway' | 'none';
    21|
    22|export type TaskType =
    23|  | 'chat'
    24|  | 'code_generation'
    25|  | 'code_planning'
    26|  | 'analysis'
    27|  | 'summary';
    28|
    29|export interface ProviderConfig {
    30|  name: ProviderName;
    31|  enabled: boolean;
    32|  apiKeyEnvVar: string;
    33|  baseUrl: string;
    34|  defaultModel: string;
    35|  maxOutputTokens: number;
    36|  timeoutMs: number;
    37|  priority: number;
    38|}
    39|
    40|export interface ChatCompletionRequest {
    41|  system: string;
    42|  user: string;
    43|  maxOutputTokens?: number;
    44|  temperature?: number;
    45|  taskType?: TaskType;
    46|  abortSignal?: AbortSignal | null;
    47|  requestId?: string;
    48|}
    49|
    50|export interface ChatCompletionResponse {
    51|  text: string;
    52|  model: string;
    53|  provider: ProviderName;
    54|  inputTokens: number;
    55|  outputTokens: number;
    56|  costUsd: number;
    57|  latencyMs: number;
    58|  requestId: string;
    59|}
    60|
    61|export interface ProviderHealth {
    62|  provider: ProviderName;
    63|  healthy: boolean;
    64|  model: string;
    65|  lastCheckedAt: string;
    66|  lastHttpStatus: number | null;
    67|  error: string | null;
    68|}
