    95|    apiKeyEnvVar: 'IVX_OPENAI_API_KEY',
    96|    baseUrl: 'https://api.openai.com/v1/chat/completions',
    97|    defaultModel: 'gpt-4o',
    98|    maxOutputTokens: 8192,
    99|    timeoutMs: 90_000,
   100|    priority: 1,
