   140|// ── Cost tracking (in-memory, reset daily) ────────────────────────────────
   141|
   142|let costTracker: CostTracker = {
   143|  dailySpendUsd: 0,
   144|  monthlySpendUsd: 0,
   145|  dailyLimitUsd: 50,
   146|  monthlyLimitUsd: 500,
   147|  emergencyStopActive: false,
   148|  lastResetDate: new Date().toISOString().slice(0, 10),
   149|};
   150|
   151|function resetDailyCostIfNeeded(): void {
   152|  const today = new Date().toISOString().slice(0, 10);
   153|  if (costTracker.lastResetDate !== today) {
   154|    costTracker.dailySpendUsd = 0;
   155|    costTracker.lastResetDate = today;
   156|  }
   157|}
   158|
   159|function isBudgetExceeded(): boolean {
   160|  resetDailyCostIfNeeded();
   161|  return (
   162|    costTracker.emergencyStopActive ||
   163|    costTracker.dailySpendUsd >= costTracker.dailyLimitUsd ||
   164|    costTracker.monthlySpendUsd >= costTracker.monthlyLimitUsd
   165|  );
   166|}
   167|
   168|function recordCost(usd: number): void {
   169|  resetDailyCostIfNeeded();
   170|  costTracker.dailySpendUsd += usd;
   171|  costTracker.monthlySpendUsd += usd;
   172|}
   173|
   174|// ── Owner controls ────────────────────────────────────────────────────────
   175|
   176|export function setEmergencyStop(active: boolean): void {
   177|  costTracker.emergencyStopActive = active;
   178|}
   179|
   180|export function setDailyLimit(usd: number): void {
   181|  costTracker.dailyLimitUsd = usd;
   182|}
   183|
   184|export function setMonthlyLimit(usd: number): void {
   185|  costTracker.monthlyLimitUsd = usd;
   186|}
   187|
   188|export function getCostTracker(): CostTracker {
   189|  resetDailyCostIfNeeded();
   190|  return { ...costTracker };
   191|}
   192|
   193|// ── Token estimation ──────────────────────────────────────────────────────
   194|
   195|export function estimateTokens(text: string): number {
   196|  return Math.ceil(text.length / 4);
   197|}
   198|
   199|function estimateCostUsd(
   200|  inputTokens: number,
   201|  outputTokens: number,
   202|  model: string,
   203|): number {
   204|  if (model.includes('gpt-4o-mini')) {
   205|    return (inputTokens * 0.00000015) + (outputTokens * 0.0000006);
   206|  }
   207|  if (model.includes('gpt-4o')) {
   208|    return (inputTokens * 0.0000025) + (outputTokens * 0.00001);
   209|  }
   210|  if (model.includes('claude')) {
   211|    return (inputTokens * 0.000003) + (outputTokens * 0.000015);
   212|  }
   213|  return (inputTokens * 0.0000025) + (outputTokens * 0.00001);
   214|}
   215|
   216|// ── Error normalization ───────────────────────────────────────────────────
   217|
   218|export interface ProviderError {
   219|  provider: ProviderName;
   220|  type: 'timeout' | 'auth' | 'rate_limit' | 'network' | 'server' | 'unknown';
   221|  message: string;
   222|  httpStatus: number | null;
   223|  retryable: boolean;
   224|}
   225|
   226|function normalizeError(
   227|  provider: ProviderName,
   228|  error: unknown,
   229|): ProviderError {
   230|  const msg = error instanceof Error ? error.message : String(error);
   231|  const lower = msg.toLowerCase();
   232|
   233|  if (lower.includes('timeout') || lower.includes('aborted')) {
   234|    return { provider, type: 'timeout', message: msg, httpStatus: null, retryable: true };
   235|  }
   236|  if (lower.includes('401') || lower.includes('auth') || lower.includes('api key')) {
   237|    return { provider, type: 'auth', message: msg, httpStatus: 401, retryable: false };
   238|  }
   239|  if (lower.includes('429') || lower.includes('rate limit')) {
   240|    return { provider, type: 'rate_limit', message: msg, httpStatus: 429, retryable: true };
   241|  }
   242|  if (lower.includes('network') || lower.includes('connect') || lower.includes('econnrefused')) {
   243|    return { provider, type: 'network', message: msg, httpStatus: null, retryable: true };
   244|  }
   245|  if (lower.includes('500') || lower.includes('502') || lower.includes('503')) {
   246|    return { provider, type: 'server', message: msg, httpStatus: 503, retryable: true };
   247|  }
   248|  return { provider, type: 'unknown', message: msg, httpStatus: null, retryable: false };
   249|}
   250|
   251|// ── Provider router ───────────────────────────────────────────────────────
   252|
   253|let routerConfig: ProviderRouterConfig = DEFAULT_ROUTER_CONFIG;
   254|
   255|export function getRouterConfig(): ProviderRouterConfig {
   256|  return routerConfig;
   257|}
   258|
   259|export function setRouterConfig(config: Partial<ProviderRouterConfig>): void {
   260|  routerConfig = { ...routerConfig, ...config };
   261|}
   262|
   263|export function setPrimaryProvider(name: ProviderName): void {
   264|  routerConfig.primaryProvider = name;
   265|}
   266|
   267|export function setFallbackProvider(name: ProviderName | null): void {
   268|  routerConfig.fallbackProvider = name;
   269|}
   270|
   271|export function enableProvider(name: ProviderName, enabled: boolean): void {
   272|  const provider = routerConfig.providers.find((p) => p.name === name);
   273|  if (provider) provider.enabled = enabled;
   274|}
   275|
   276|export function setModelForTask(task: TaskType, model: string): void {
   277|  routerConfig.modelByTask[task] = model;
   278|}
   279|
   280|function getProviderConfig(name: ProviderName): ProviderConfig | null {
   281|  return routerConfig.providers.find((p) => p.name === name && p.enabled) ?? null;
   282|}
   283|
   284|function getApiKey(config: ProviderConfig): string {
   285|  const value = process.env[config.apiKeyEnvVar];
   286|  return typeof value === 'string' ? value.trim() : '';
   287|}
   288|
   289|// ── Health check ──────────────────────────────────────────────────────────
   290|
   291|export async function checkProviderHealth(
   292|  name: ProviderName,
   293|): Promise<ProviderHealth> {
   294|  const config = getProviderConfig(name);
   295|  if (!config) {
   296|    return {
   297|      provider: name,
   298|      healthy: false,
   299|      model: 'N/A',
   300|      lastCheckedAt: new Date().toISOString(),
   301|      lastHttpStatus: null,
   302|      error: 'Provider not configured or disabled',
   303|    };
   304|  }
   305|
   306|  const apiKey = getApiKey(config);
   307|  if (!apiKey) {
   308|    return {
   309|      provider: name,
   310|      healthy: false,
   311|      model: config.defaultModel,
   312|      lastCheckedAt: new Date().toISOString(),
   313|      lastHttpStatus: null,
   314|      error: `No API key found in ${config.apiKeyEnvVar}`,
   315|    };
   316|  }
   317|
   318|  try {
   319|    const response = await fetch(config.baseUrl, {
   320|      method: 'POST',
   321|      headers: {
   322|        'Content-Type': 'application/json',
   323|        Authorization: `Bearer ${apiKey}`,
   324|      },
   325|      body: JSON.stringify({
   326|        model: config.defaultModel,
   327|        messages: [{ role: 'user', content: 'ping' }],
   328|        max_tokens: 1,
   329|      }),
   330|      signal: AbortSignal.timeout(10_000),
   331|    });
   332|
   333|    return {
   334|      provider: name,
   335|      healthy: response.ok || response.status === 400,
   336|      model: config.defaultModel,
   337|      lastCheckedAt: new Date().toISOString(),
   338|      lastHttpStatus: response.status,
   339|      error: response.ok ? null : `HTTP ${response.status}`,
   340|    };
   341|  } catch (error) {
   342|    return {
   343|      provider: name,
   344|      healthy: false,
   345|      model: config.defaultModel,
   346|      lastCheckedAt: new Date().toISOString(),
   347|      lastHttpStatus: null,
   348|      error: error instanceof Error ? error.message : String(error),
   349|    };
   350|  }
   351|}
   352|
   353|// ── Chat completion with failover ─────────────────────────────────────────
   354|
   355|const MAX_RETRIES = 3;
   356|const BASE_BACKOFF_MS = 1000;
   357|
   358|function computeBackoff(attempt: number): number {
   359|  return Math.min(BASE_BACKOFF_MS * Math.pow(2, attempt), 30_000);
   360|}
   361|
   362|async function callOpenAI(
   363|  config: ProviderConfig,
   364|  request: ChatCompletionRequest,
   365|  apiKey: string,
   366|): Promise<ChatCompletionResponse> {
   367|  const model =
   368|    (request.taskType && routerConfig.modelByTask[request.taskType]) ||
   369|    config.defaultModel;
   370|  const maxTokens = request.maxOutputTokens ?? config.maxOutputTokens;
   371|  const startTime = Date.now();
   372|  const requestId = request.requestId || `ivx-ai-${Date.now()}`;
   373|
   374|  const response = await fetch(config.baseUrl, {
   375|    method: 'POST',
   376|    headers: {
   377|      'Content-Type': 'application/json',
   378|      Authorization: `Bearer ${apiKey}`,
   379|    },
   380|    body: JSON.stringify({
   381|      model,
   382|      messages: [
   383|        { role: 'system', content: request.system },
   384|        { role: 'user', content: request.user },
   385|      ],
   386|      max_tokens: maxTokens,
   387|      temperature: request.temperature ?? 0.7,
   388|    }),
   389|    signal: request.abortSignal ?? undefined,
   390|  });
   391|
   392|  if (!response.ok) {
   393|    const body = await response.text().catch(() => '');
   394|    throw new Error(`HTTP ${response.status}: ${body.slice(0, 200)}`);
   395|  }
   396|
   397|  const data = await response.json();
   398|  const text = data.choices?.[0]?.message?.content ?? '';
   399|  const inputTokens = data.usage?.prompt_tokens ?? estimateTokens(request.system + request.user);
   400|  const outputTokens = data.usage?.completion_tokens ?? estimateTokens(text);
   401|  const costUsd = estimateCostUsd(inputTokens, outputTokens, model);
   402|  const latencyMs = Date.now() - startTime;
   403|
   404|  recordCost(costUsd);
   405|
   406|  return {
   407|    text,
   408|    model,
   409|    provider: 'openai',
   410|    inputTokens,
   411|    outputTokens,
   412|    costUsd,
   413|    latencyMs,
   414|    requestId,
   415|  };
   416|}
