   427|  const startTime = Date.now();
   428|  const requestId = request.requestId || `ivx-ai-${Date.now()}`;
   429|
   430|  const response = await fetch(config.baseUrl, {
   431|    method: 'POST',
   432|    headers: {
   433|      'Content-Type': 'application/json',
   434|      'x-api-key': apiKey,
   435|      'anthropic-version': '2023-06-01',
   436|    },
   437|    body: JSON.stringify({
   438|      model,
   439|      system: request.system,
