   443|    signal: request.abortSignal ?? undefined,
   444|  });
   445|
   446|  if (!response.ok) {
   447|    const body = await response.text().catch(() => '');
   448|    throw new Error(`HTTP ${response.status}: ${body.slice(0, 200)}`);
   449|  }
   450|
   451|  const data = await response.json();
   452|  const text = data.content?.[0]?.text ?? '';
   453|  const inputTokens = data.usage?.input_tokens ?? estimateTokens(request.system + request.user);
   454|  const outputTokens = data.usage?.output_tokens ?? estimateTokens(text);
   455|  const costUsd = estimateCostUsd(inputTokens, outputTokens, model);
   456|  const latencyMs = Date.now() - startTime;
   457|
   458|  recordCost(costUsd);
   459|
   460|  return {
   461|    text,
   462|    model,
   463|    provider: 'anthropic',
