   472|export async function chatCompletion(
   473|  request: ChatCompletionRequest,
   474|): Promise<ChatCompletionResponse> {
   475|  if (isBudgetExceeded()) {
   476|    throw new Error(
   477|      `Budget exceeded or emergency stop active. Daily: $${costTracker.dailySpendUsd.toFixed(2)}/$${costTracker.dailyLimitUsd}, Monthly: $${costTracker.monthlySpendUsd.toFixed(2)}/$${costTracker.monthlyLimitUsd}`,
   478|    );
   479|  }
   480|
   481|  const providersToTry: ProviderName[] = [
   482|    routerConfig.primaryProvider,
   483|    ...(routerConfig.fallbackProvider ? [routerConfig.fallbackProvider] : []),
   484|  ];
   485|
   486|  let lastError: ProviderError | null = null;
   487|
   488|  for (const providerName of providersToTry) {
   489|    const config = getProviderConfig(providerName);
   490|    if (!config) continue;
   491|
   492|    const apiKey = getApiKey(config);
   493|    if (!apiKey) {
   494|      lastError = {
   495|        provider: providerName,
   496|        type: 'auth',
   497|        message: `No API key in ${config.apiKeyEnvVar}`,
   498|        httpStatus: null,
   499|        retryable: false,
   500|      };
   501|      continue;
   502|    }
   503|
   504|    for (let attempt = 0; attempt < MAX_RETRIES; attempt++) {
   505|      try {
   506|        if (providerName === 'openai' || providerName === 'vercel_gateway') {
   507|          return await callOpenAI(config, request, apiKey);
   508|        }
   509|        if (providerName === 'anthropic') {
   510|          return await callAnthropic(config, request, apiKey);
   511|        }
   512|        throw new Error(`Unknown provider: ${providerName}`);
   513|      } catch (error) {
   514|        lastError = normalizeError(providerName, error);
   515|        if (!lastError.retryable || attempt === MAX_RETRIES - 1) break;
   516|        const backoff = computeBackoff(attempt);
   517|        await new Promise((resolve) => setTimeout(resolve, backoff));
   518|      }
   519|    }
   520|  }
   521|
   522|  throw new Error(
   523|    `All providers failed. Last error: ${lastError?.provider ?? 'none'} — ${lastError?.message ?? 'unknown'}`,
   524|  );
   525|}
