   536|export function getProviderLayerStatus(): {
   537|  ready: boolean;
   538|  primaryProvider: ProviderName;
   539|  fallbackProvider: ProviderName | null;
   540|  primaryKeyConfigured: boolean;
   541|  fallbackKeyConfigured: boolean;
   542|  emergencyStopActive: boolean;
   543|  dailySpendUsd: number;
   544|  monthlySpendUsd: number;
   545|  dailyLimitUsd: number;
   546|  monthlyLimitUsd: number;
   547|} {
   548|  const primary = getProviderConfig(routerConfig.primaryProvider);
   549|  const fallback = routerConfig.fallbackProvider
   550|    ? getProviderConfig(routerConfig.fallbackProvider)
   551|    : null;
   552|
   553|  return {
   554|    ready: isIVXProviderLayerReady(),
   555|    primaryProvider: routerConfig.primaryProvider,
   556|    fallbackProvider: routerConfig.fallbackProvider,
   557|    primaryKeyConfigured: primary ? getApiKey(primary).length > 0 : false,
   558|    fallbackKeyConfigured: fallback ? getApiKey(fallback).length > 0 : false,
   559|    emergencyStopActive: costTracker.emergencyStopActive,
   560|    dailySpendUsd: costTracker.dailySpendUsd,
   561|    monthlySpendUsd: costTracker.monthlySpendUsd,
   562|    dailyLimitUsd: costTracker.dailyLimitUsd,
   563|    monthlyLimitUsd: costTracker.monthlyLimitUsd,
   564|  };
